export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryPlan {
  prefix: string;
  maxNights: number;
  minStay?: number;
  maxGuests: number;
  base: number;
  highSurcharge: number;
  extra: (guests: number) => number;
}

const PLANS: Record<string, CategoryPlan> = {
  standard: { prefix: "standard", maxNights: 14, maxGuests: 2, base: 80, highSurcharge: 30, extra: () => 0 },
  suite: { prefix: "suite", maxNights: 21, maxGuests: 4, base: 150, highSurcharge: 60, extra: (guests) => (guests > 2 ? 25 : 0) },
  villa: { prefix: "villa", maxNights: 28, minStay: 3, maxGuests: 8, base: 300, highSurcharge: 120, extra: () => 500 },
};

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
