cd /tmp/eval-work-ajQfmE && cat > orig.ts <<'EOF'
export function orig(raw: any): any {
  const req = raw as any;
  if (req.category === "standard") {
    let total = 80 * req.nights; if (req.season === "high") total += 30 * req.nights;
    if (req.loyaltyYears >= 3 || req.coupon === "VIP") total -= Math.floor(total/10);
    let policy = "strict"; if (req.coupon === "VIP" || req.loyaltyYears > 2) policy = "flex";
    return {ok:true,total,policy,line:"standard:"+req.nights+"n:"+total+":"+policy};
  }
  if (req.category === "suite") {
    let total = 150 * req.nights; if (req.season === "high") total += 60 * req.nights;
    if (req.coupon === "VIP" || req.loyaltyYears >= 3) total -= Math.floor(total/10);
    if (req.guests > 2) total += 25;
    let policy = "strict"; if (!(req.loyaltyYears < 3) || req.coupon === "VIP") policy = "flex";
    return {ok:true,total,policy,line:"suite:"+req.nights+"n:"+total+":"+policy};
  }
  if (req.category === "villa") {
    let total = 300 * req.nights; if (req.season === "high") total += 120 * req.nights;
    if (req.loyaltyYears > 2 || req.coupon === "VIP") total -= Math.floor(total/10);
    total += 500;
    let policy = "strict"; if (req.coupon === "VIP" || !(req.loyaltyYears < 3)) policy = "flex";
    return {ok:true,total,policy,line:"villa:"+req.nights+"n:"+total+":"+policy};
  }
  return {ok:false,error:"unknown category"};
}
EOF
cat > t.ts <<'EOF'
import { quoteBooking } from './quote_booking';
import { orig } from './orig';
const cats = ["standard","suite","villa","x"];
let ok=0,fail=0;
for (const category of cats)
 for (let nights=0;nights<=30;nights++)
  for (let guests=0;guests<=10;guests++)
   for (const season of ["low","high","mid"])
    for (const loyaltyYears of [0,2,3,5])
     for (const coupon of ["VIP","NONE"])
      for (const loyal of [{loyaltyYears}, {loyaltyYears:"x"}]) {
        const raw = {category,nights,guests,season,coupon,...loyal};
        const a = quoteBooking(raw), b = orig(raw);
        if (JSON.stringify(a)!==JSON.stringify(b)) { fail++; console.log("MISMATCH", raw, a, b); }
        else ok++;
      }
console.log("ok",ok,"fail",fail);
EOF
npx tsx t.ts 2>/dev/null || npx ts-node t.ts 2>/dev/null || (npm i -D tsx >/dev/null 2>&1 && npx tsx t.ts)

