arguments.content:
export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryPlan {
  prefix: string;
  maxNights: number;
  minStay?: number;
  maxGuests: number;
  base: number;
  highSurcharge: number;
  extra: (guests: number) => number;
}

const PLANS: Record<string, CategoryPlan> = {
  standard: { prefix: "standard", maxNights: 14, maxGuests: 2, base: 80, highSurcharge: 30, extra: () => 0 },
  suite: { prefix: "suite", maxNights: 21, maxGuests: 4, base: 150, highSurcharge: 60, extra: (guests) => (guests > 2 ? 25 : 0) },
  villa: { prefix: "villa", maxNights: 28, minStay: 3, maxGuests: 8, base: 300, highSurcharge: 120, extra: () => 500 },
};

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const plan = PLANS[req.category as string];
  if (plan === undefined) {
    return { ok: false, error: "unknown category" };
  }

  const nights = req.nights as number;
  const guests = req.guests as number;
  const vip = req.coupon === "VIP";
  const loyalty = req.loyaltyYears as number;

  if (!Number.isInteger(nights) || nights < 1 || nights > plan.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (plan.minStay !== undefined && nights < plan.minStay) {
    return { ok: false, error: "villa minimum stay" };
  }
  if (!Number.isInteger(guests) || guests < 1 || guests > plan.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  if (req.season !== "low" && req.season !== "high") {
    return { ok: false, error: "bad season" };
  }

  let total = plan.base * nights;
  if (req.season === "high") {
    total += plan.highSurcharge * nights;
  }
  if (vip || loyalty >= 3) {
    total -= Math.floor(total / 10);
  }
  total += plan.extra(guests);

  const policy = vip || loyalty >= 3 ? "flex" : "strict";
  const line = `${plan.prefix}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

